#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static long heap[16];
static int size = 0;

static void heap_insert(long val) {
    if (size >= 16) {
        puts("FULL");
        return;
    }
    heap[size] = val;
    int i = size;
    size++;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p] <= heap[i]) break;
        long tmp = heap[p];
        heap[p] = heap[i];
        heap[i] = tmp;
        i = p;
    }
    printf("INS %ld\n", val);
}

static void heap_extract(void) {
    if (size == 0) {
        puts("EMPTY");
        return;
    }
    long min = heap[0];
    heap[0] = heap[size - 1];
    size--;
    int i = 0;
    while (1) {
        int left = 2 * i + 1;
        int right = left + 1;
        if (left >= size) break;
        int smallest = left;
        if (right < size && heap[right] < heap[left])
            smallest = right;
        if (heap[i] <= heap[smallest]) break;
        long tmp = heap[i];
        heap[i] = heap[smallest];
        heap[smallest] = tmp;
        i = smallest;
    }
    printf("MIN %ld\n", min);
}

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }
    for (int idx = 1; idx < argc; ++idx) {
        char *arg = argv[idx];
        if (arg[0] == 'I') {
            char *end;
            long val = strtol(arg + 1, &end, 10);
            if (end == arg + 1 || *end != '\0') {
                puts("ERR");
                continue;
            }
            heap_insert(val);
        } else if (strcmp(arg, "X") == 0) {
            heap_extract();
        } else {
            puts("ERR");
        }
    }
    return 0;
}
